	router.GET("/config-versions", srv.handleHistory)
	router.GET("/config-item-histories", srv.handleItemHistory)
	router.GET("/namespaces/:namespace/environments/:environment/config-versions/:version", srv.handleVersionSnapshot)

	// Publishing and rollback entry points that feed the stored version history.
	router.POST("/namespaces/:namespace/environments/:environment/config-versions", srv.handlePublish)
	router.POST("/namespaces/:namespace/environments/:environment/config-versions/:version/rollback", srv.handleRollback)
	router.POST("/namespaces/:namespace/environments/:environment/config-versions/:version/promote", srv.handlePromote)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}
package api

import (
	"encoding/json"

	"github.com/luwa07832/config-center-api/internal/store"
)

// ItemChange is one change of a single item between two consecutive stored versions.
type ItemChange struct {
	Version  VersionInfo      `json:"version"`
	Type     string           `json:"changeType"`
	OldValue *json.RawMessage `json:"oldValue,omitempty"`
	NewValue *json.RawMessage `json:"newValue,omitempty"`
}

// EffectiveItemState reports whether the item exists in the latest full release and, when it
// does, its stored raw JSON value.
type EffectiveItemState struct {
	Present bool             `json:"present"`
	Value   *json.RawMessage `json:"value,omitempty"`
}

// ItemHistoryResponse is the read-only per-item history.
type ItemHistoryResponse struct {
	Namespace        string             `json:"namespace"`
	Environment      string             `json:"environment"`
	Name             string             `json:"name"`
	EffectiveVersion *int64             `json:"effectiveVersion"`
	EffectiveItem    EffectiveItemState `json:"effectiveItem"`
	Changes          []ItemChange       `json:"changes"`
	TotalChanges     int                `json:"totalChanges"`
}

// BuildItemHistory compares one item's value in each version with the immediately preceding
// version of the same scope. Gray releases and rollback copies participate; unchanged versions
// are skipped. Inputs must be ordered by version ascending.
func BuildItemHistory(namespace, environment, name string,
	history []store.ItemVersionValue, effectiveValue json.RawMessage, effectiveHas bool, effectiveVersion int64) ItemHistoryResponse {
	changes := make([]ItemChange, 0)
	var previous string
	hadPrevious := false
	for _, entry := range history {
		switch {
		case entry.HasValue && !hadPrevious:
			newValue := json.RawMessage(entry.Value)
			changes = append(changes, ItemChange{
				Version:  toVersionInfo(entry.Version, effectiveVersion),
				Type:     changeAdded,
				NewValue: &newValue,
			})
		case hadPrevious && !entry.HasValue:
			oldValue := json.RawMessage(previous)
			changes = append(changes, ItemChange{
				Version:  toVersionInfo(entry.Version, effectiveVersion),
				Type:     changeRemoved,
				OldValue: &oldValue,
			})
		case hadPrevious && entry.HasValue && entry.Value != previous:
			oldValue := json.RawMessage(previous)
			newValue := json.RawMessage(entry.Value)
			changes = append(changes, ItemChange{
				Version:  toVersionInfo(entry.Version, effectiveVersion),
				Type:     changeModified,
				OldValue: &oldValue,
				NewValue: &newValue,
			})
		}
		if entry.HasValue {
			previous = entry.Value
			hadPrevious = true
		} else {
			hadPrevious = false
		}
	}

	effectiveItem := EffectiveItemState{Present: false}
	if effectiveHas {
		value := effectiveValue
		effectiveItem = EffectiveItemState{Present: true, Value: &value}
	}
	return ItemHistoryResponse{
		Namespace:        namespace,
		Environment:      environment,
		Name:             name,
		EffectiveVersion: intPtrOrNil(effectiveVersion),
		EffectiveItem:    effectiveItem,
		Changes:          changes,
		TotalChanges:     len(changes),
	}
}
package api

import (
	"encoding/json"
	"sort"
)

// EffectiveConfigChange is one item-level difference between the effective snapshots of two
// environments. It carries no affectsEffectiveConfig flag because that notion only applies to
// versions inside a single environment.
type EffectiveConfigChange struct {
	Name     string           `json:"name"`
	Type     string           `json:"changeType"`
	OldValue *json.RawMessage `json:"oldValue,omitempty"`
	NewValue *json.RawMessage `json:"newValue,omitempty"`
}

// EffectiveConfigDiffResponse is the complete result of comparing the effective snapshots of
// two environments in one namespace. Version fields are nil when a side has no full release.
type EffectiveConfigDiffResponse struct {
	Namespace         string                  `json:"namespace"`
	BaseEnvironment   string                  `json:"baseEnvironment"`
	TargetEnvironment string                  `json:"targetEnvironment"`
	BaseVersion       *VersionInfo            `json:"baseVersion"`
	TargetVersion     *VersionInfo            `json:"targetVersion"`
	ChangedCount      int                     `json:"changedCount"`
	Changes           []EffectiveConfigChange `json:"changes"`
}

// BuildEffectiveConfigDiff diffs the stored items of two effective snapshots. An empty items
// map represents a scope without an effective release, so every item on the other side becomes
// an added or removed change. Changes are ordered by item name.
func BuildEffectiveConfigDiff(namespace, baseEnvironment, targetEnvironment string,
	baseVersion, targetVersion *VersionInfo,
	baseItems, targetItems map[string]json.RawMessage) EffectiveConfigDiffResponse {
	names := make(map[string]struct{}, len(baseItems)+len(targetItems))
	for name := range baseItems {
		names[name] = struct{}{}
	}
	for name := range targetItems {
		names[name] = struct{}{}
	}
	ordered := make([]string, 0, len(names))
	for name := range names {
		ordered = append(ordered, name)
	}
	sort.Strings(ordered)

	changes := make([]EffectiveConfigChange, 0, len(ordered))
	for _, name := range ordered {
		oldValue, hadOld := baseItems[name]
		newValue, hasNew := targetItems[name]
		change, changed := buildChange(name, oldValue, hadOld, newValue, hasNew)
		if !changed {
			continue
		}
		changes = append(changes, EffectiveConfigChange{
			Name:     change.Name,
			Type:     change.Type,
			OldValue: change.OldValue,
			NewValue: change.NewValue,
		})
	}
	return EffectiveConfigDiffResponse{
		Namespace:         namespace,
		BaseEnvironment:   baseEnvironment,
		TargetEnvironment: targetEnvironment,
		BaseVersion:       baseVersion,
		TargetVersion:     targetVersion,
		ChangedCount:      len(changes),
		Changes:           changes,
	}
}

